CREATE TABLE public.referral_vip_campaign(id boolean PRIMARY KEY DEFAULT true CHECK(id), started_at timestamptz NOT NULL DEFAULT now(), details_at timestamptz NOT NULL DEFAULT now()+interval '15 days', event_label text NOT NULL DEFAULT 'డిసెంబర్ 31');
GRANT SELECT ON public.referral_vip_campaign TO anon,authenticated; GRANT ALL ON public.referral_vip_campaign TO service_role;
ALTER TABLE public.referral_vip_campaign ENABLE ROW LEVEL SECURITY;
CREATE POLICY campaign_read ON public.referral_vip_campaign FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY campaign_update ON public.referral_vip_campaign FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
GRANT UPDATE(event_label) ON public.referral_vip_campaign TO authenticated;
CREATE TABLE public.referral_vip_joins(joined_user uuid PRIMARY KEY REFERENCES public.profiles(id), referrer_id uuid NOT NULL REFERENCES public.profiles(id), joined_at timestamptz NOT NULL DEFAULT now(), CHECK(joined_user<>referrer_id));
GRANT SELECT ON public.referral_vip_joins TO authenticated; GRANT ALL ON public.referral_vip_joins TO service_role;
ALTER TABLE public.referral_vip_joins ENABLE ROW LEVEL SECURITY;
CREATE POLICY joins_read ON public.referral_vip_joins FOR SELECT TO authenticated USING(auth.uid() IN(joined_user,referrer_id) OR public.has_role(auth.uid(),'admin'));
CREATE INDEX vip_referrer_index ON public.referral_vip_joins(referrer_id);
CREATE TABLE public.referral_cash_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), reference text NOT NULL UNIQUE, amount_paise bigint NOT NULL CHECK(amount_paise>0), confirmed_by uuid NOT NULL REFERENCES public.profiles(id), received_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.referral_cash_receipts TO authenticated; GRANT ALL ON public.referral_cash_receipts TO service_role;
ALTER TABLE public.referral_cash_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY receipt_read ON public.referral_cash_receipts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.referral_cash_rewards(receipt_id uuid PRIMARY KEY REFERENCES public.referral_cash_receipts(id), user_id uuid NOT NULL REFERENCES public.profiles(id), amount_paise bigint NOT NULL CHECK(amount_paise>0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.referral_cash_rewards TO authenticated; GRANT ALL ON public.referral_cash_rewards TO service_role;
ALTER TABLE public.referral_cash_rewards ENABLE ROW LEVEL SECURITY;
CREATE POLICY rewards_read ON public.referral_cash_rewards FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.referral_vip_notice_state(user_id uuid PRIMARY KEY REFERENCES public.profiles(id), signature text NOT NULL);
GRANT ALL ON public.referral_vip_notice_state TO service_role;
ALTER TABLE public.referral_vip_notice_state ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.referral_vip_ranks() RETURNS TABLE(user_id uuid,joins bigint,rank_no bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT referrer_id,count(*),row_number() OVER(ORDER BY count(*) DESC,min(joined_at),referrer_id) FROM public.referral_vip_joins WHERE public.account_allowed(referrer_id) GROUP BY referrer_id $$;
REVOKE ALL ON FUNCTION public.referral_vip_ranks() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.refresh_referral_vip_notices() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record; n bigint; r bigint; cutoff bigint; needed bigint; sig text; previous text; body text; sent integer:=0; BEGIN PERFORM pg_advisory_xact_lock(781105); SELECT coalesce(min(joins),0) INTO cutoff FROM public.referral_vip_ranks() WHERE rank_no<=100; FOR p IN SELECT id FROM public.profiles WHERE public.account_allowed(id) LOOP SELECT joins,rank_no INTO n,r FROM public.referral_vip_ranks() WHERE user_id=p.id; n:=coalesce(n,0); needed:=CASE WHEN r<=100 THEN 0 WHEN (SELECT count(*) FROM public.referral_vip_ranks())<100 THEN 1 ELSE greatest(1,cutoff-n+1) END; sig:=CASE WHEN needed=0 THEN 'vip' ELSE 'need:'||needed END; SELECT signature INTO previous FROM public.referral_vip_notice_state WHERE user_id=p.id; IF previous IS NOT DISTINCT FROM sig OR NOT public.can_notify(p.id) THEN CONTINUE; END IF; body:=CASE WHEN needed=0 THEN 'మీరు మొదటి వంద స్థానాల్లో ఉన్నారు; ప్రత్యేక ప్రవేశ అర్హత పొందారు. వేడుక పూర్తి వివరాలు మరో పదిహేను రోజుల్లో తెలియజేస్తాం.' ELSE 'మొదటి వంద స్థానాల్లోకి రావడానికి ఇంకా '||needed||' మందిని మీ సంకేతంతో చేర్పించండి. ప్రస్తుత చేరికలు: '||n||'. ఇతరుల చేరికలతో స్థానాలు మారవచ్చు.' END; INSERT INTO public.notifications(user_id,message) VALUES(p.id,body); INSERT INTO public.referral_vip_notice_state(user_id,signature) VALUES(p.id,sig) ON CONFLICT(user_id) DO UPDATE SET signature=excluded.signature; sent:=sent+1; END LOOP; RETURN sent; END $$;
REVOKE ALL ON FUNCTION public.refresh_referral_vip_notices() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.refresh_referral_vip_notices() TO service_role;
CREATE OR REPLACE FUNCTION public.apply_referral(_code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE me public.profiles; ref public.profiles; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RETURN false; END IF; PERFORM pg_advisory_xact_lock(781105); SELECT * INTO me FROM public.profiles WHERE id=auth.uid() FOR UPDATE; IF me.id IS NULL OR EXISTS(SELECT 1 FROM public.referral_vip_joins WHERE joined_user=me.id) THEN RETURN false; END IF; SELECT * INTO ref FROM public.profiles WHERE referral_code=upper(trim(_code)); IF ref.id IS NULL OR ref.id=me.id OR NOT public.account_allowed(ref.id) THEN RETURN false; END IF; IF EXISTS(WITH RECURSIVE ancestors(id) AS (SELECT ref.id UNION SELECT j.referrer_id FROM public.referral_vip_joins j JOIN ancestors a ON j.joined_user=a.id) SELECT 1 FROM ancestors WHERE id=me.id) THEN RETURN false; END IF; INSERT INTO public.referral_vip_campaign(id) VALUES(true) ON CONFLICT DO NOTHING; INSERT INTO public.referral_vip_joins(joined_user,referrer_id) VALUES(me.id,ref.id); PERFORM set_config('app.trusted','1',true); UPDATE public.profiles SET referred_by=ref.id,referred_at=now() WHERE id=me.id; PERFORM set_config('app.trusted','',true); PERFORM public.ensure_my_referral_code(); PERFORM public.refresh_referral_vip_notices(); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.apply_referral(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.apply_referral(text) TO authenticated;
CREATE FUNCTION public.confirm_referral_cash(_user uuid,_reference text,_amount_paise bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE receipt uuid; ref uuid; prize bigint; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; IF _amount_paise<=0 OR _amount_paise>100000000000 OR length(trim(_reference))<3 OR length(trim(_reference))>120 THEN RAISE EXCEPTION 'INVALID_RECEIPT'; END IF; INSERT INTO public.referral_vip_campaign(id) VALUES(true) ON CONFLICT DO NOTHING; INSERT INTO public.referral_cash_receipts(user_id,reference,amount_paise,confirmed_by) VALUES(_user,trim(_reference),_amount_paise,auth.uid()) RETURNING id INTO receipt; SELECT referrer_id INTO ref FROM public.referral_vip_joins WHERE joined_user=_user; IF ref IS NOT NULL THEN prize:=(_amount_paise*20)/100; IF prize>0 THEN INSERT INTO public.referral_cash_rewards(receipt_id,user_id,amount_paise) VALUES(receipt,ref,prize); IF public.can_notify(ref) THEN INSERT INTO public.notifications(user_id,message) VALUES(ref,'నిర్ధారించిన చెల్లింపుపై 20% నగదు బహుమతి ₹'||(prize::numeric/100)||' మీ లెక్కలో నమోదైంది; బ్యాంకుకు పంపినట్లు కాదు.'); END IF; END IF; END IF; RETURN receipt; END $$;
REVOKE ALL ON FUNCTION public.confirm_referral_cash(uuid,text,bigint) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.confirm_referral_cash(uuid,text,bigint) TO authenticated;
CREATE FUNCTION public.my_referral_vip() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n bigint; r bigint; cutoff bigint; needed bigint; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; SELECT joins,rank_no INTO n,r FROM public.referral_vip_ranks() WHERE user_id=auth.uid(); SELECT coalesce(min(joins),0) INTO cutoff FROM public.referral_vip_ranks() WHERE rank_no<=100; needed:=CASE WHEN r<=100 THEN 0 WHEN (SELECT count(*) FROM public.referral_vip_ranks())<100 THEN 1 ELSE greatest(1,cutoff-coalesce(n,0)+1) END; RETURN jsonb_build_object('count',coalesce(n,0),'rank',r,'needed',needed,'vip',coalesce(r<=100,false),'reward_paise',(SELECT coalesce(sum(amount_paise),0) FROM public.referral_cash_rewards WHERE user_id=auth.uid()),'code',public.ensure_my_referral_code(),'invited_by',(SELECT referrer_id FROM public.referral_vip_joins WHERE joined_user=auth.uid())); END $$;
REVOKE ALL ON FUNCTION public.my_referral_vip() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_referral_vip() TO authenticated;
CREATE FUNCTION public.admin_broadcast(_message text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record; sent integer:=0; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; IF length(trim(_message))<1 OR length(_message)>1000 THEN RAISE EXCEPTION 'INVALID_MESSAGE'; END IF; FOR p IN SELECT id FROM public.profiles WHERE public.can_notify(id) LOOP INSERT INTO public.notifications(user_id,message) VALUES(p.id,trim(_message)); sent:=sent+1; END LOOP; RETURN sent; END $$;
REVOKE ALL ON FUNCTION public.admin_broadcast(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_broadcast(text) TO authenticated;
COMMENT ON TABLE public.membership_payments IS 'Historical financial evidence preserved; retired from new public offers.';
COMMENT ON TABLE public.referral_cash_rewards IS '20 percent direct-referral confirmed cash reward, not payout. No ancestor or unspecified invitee cash awards.';